import React, { lazy, Suspense } from 'react';
import { render } from 'react-dom';
import { Router } from 'react-router-dom';
import * as serviceWorker from './serviceWorker';
import history from './history';
import './styles/App.scss'; // Assuming you want global styles

// Lazy load FontAwesome library setup
const LoadFontAwesome = lazy(() => import('./setupFontAwesome'));

// Lazy load Google Tag Manager
const LoadTagManager = lazy(() => import('./setupTagManager'));

// Lazy load Facebook Provider
const LoadFacebookProvider = lazy(() => import('./setupFacebookProvider'));

const App = lazy(() => import('./App'));

const rootElement = document.getElementById('root');

// Initializer function to check environment variables
const initializeEnvVars = () => {
  if (!process.env.REACT_APP_GTM_ID) {
    console.error("Environment variable REACT_APP_GTM_ID is not set.");
    // Handle accordingly
  }
};

// Call the initializer function
initializeEnvVars();

render(
  <Suspense fallback={<div>Loading...</div>}>
    <LoadFontAwesome />
    <LoadTagManager />
    <Router history={history}>
      <LoadFacebookProvider>
        <App />
      </LoadFacebookProvider>
    </Router>
  </Suspense>,
  rootElement
);

// Service worker code, with improved comment
// To make the app work offline and load faster, you can change
// unregister() to register(). Note: this comes with some pitfalls.
// Learn more about service workers: http://bit.ly/CRA-PWA
serviceWorker.unregister();

